    # panel is a bitmap: color 3 encodes output 8, color 1 is background.
    h, w = len(grid), len(grid[0])
    # Locate isolated rectangular panels with 1 boundary and internal 3s.
    panels=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1: continue
            for b in range(r+2,min(h,r+7)):
                for e in range(c+2,min(w,c+14)):
                    if grid[r][e]!=1 or grid[b][c]!=1 or grid[b][e]!=1: continue
                    if not(all(grid[r][x]==1 and grid[b][x]==1 for x in range(c,e+1)) and all(grid[y][c]==1 and grid[y][e]==1 for y in range(r,b+1))): continue
                    inside=[row[c+1:e] for row in grid[r+1:b]]
                    if inside and any(3 in row for row in inside):
                        # only select rectangles whose interior consists entirely of 3s
                        if all(v==3 for row in inside for v in row):
                            panels.append((len(inside)*len(inside[0]),inside))
    if panels:
        inside=max(panels,key=lambda x:x[0])[1]
        return [[8 if v==3 else 0 for v in row] for row in inside]
    return [[0]]

